import{_ as t,o as r,c as o,a2 as s}from"./chunks/framework.mRCPFc5l.js";const f=JSON.parse('{"title":"Security Notes","description":"","frontmatter":{"title":"Security Notes"},"headers":[],"relativePath":"reference/security.md","filePath":"reference/security.md","lastUpdated":1787242450000}'),a={name:"reference/security.md"};function i(n,e,c,l,d,u){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="security-notes" tabindex="-1">Security Notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security Notes&quot;">​</a></h1><ul><li>Change the default Web UI password immediately.</li><li>Restrict TCP <code>8070</code> and exporter UDP ports to trusted networks where possible.</li><li>Keep <code>nfsen-etc/</code> private; it contains <code>.htpasswd</code> and configuration.</li><li>For LibreNMS, export only <code>nfsen-data/</code> and <code>nfsen-stat/</code> read-only.</li><li>Never run two NfSen instances writing to the same live folder.</li><li>Use a VPN or TLS reverse proxy for remote dashboard access.</li><li>Do not use the default Ubuntu 24.04 nfdump <code>1.7.3</code> package to read NetLens <code>1.6.x</code> flow files. Follow the <a href="/integration/librenms.html#5--part-3-install-nfdump-on-the-librenms-server-version-rule">LibreNMS version guidance</a>.</li></ul><div class="danger custom-block"><p class="custom-block-title">One writer rule</p><p>NfSen uses SysV semaphores that exist per host. Two instances cannot coordinate over a shared folder and can corrupt each other&#39;s five-minute files.</p></div>',3)])])}const h=t(a,[["render",i]]);export{f as __pageData,h as default};
